{
  "name": "EPICS电动位移轴",
  "name_en": "EPICS Motorized Positioning Axis",
  "manufacturer": "",
  "description": "一种由EPICS motor record控制的实验室电机运动轴，通常连接线性位移台、旋转台或其他机电执行机构，用于在实验中进行精密定位、扫描、回零和行程限制管理，常见于束线、光学平台和样品操控系统。",
  "description_en": "A motorized laboratory motion axis controlled through an EPICS motor record, typically attached to a linear stage, rotation stage, or other electromechanical actuator. It is used for precision positioning, scanning, homing, and travel-limit management in beamlines, optical setups, and sample-handling systems.",
  "tag_hints": [
    "motorized positioning",
    "precision motion control",
    "linear or rotary stage",
    "sample alignment",
    "homing",
    "travel limits",
    "beamline instrumentation"
  ],
  "actions": [
    {
      "action_name": "auto-check_value",
      "description": "检查目标位置是否在软限位范围内",
      "description_en": "Check whether a target position is within the soft limits."
    },
    {
      "action_name": "auto-home",
      "description": "沿指定方向执行回零搜索",
      "description_en": "Perform a homing search in the specified direction."
    },
    {
      "action_name": "auto-move",
      "description": "移动到指定位置",
      "description_en": "Move to a specified position."
    },
    {
      "action_name": "auto-set_current_position",
      "description": "设置当前用户位置",
      "description_en": "Set the current user position."
    },
    {
      "action_name": "auto-set_lim",
      "description": "设置低位和高位行程限位",
      "description_en": "Set the low and high travel limits."
    },
    {
      "action_name": "auto-stop",
      "description": "停止运动",
      "description_en": "Stop motion."
    },
    {
      "action_name": "auto-precision",
      "description": "获取位置读回精度",
      "description_en": "Get the position readback precision."
    },
    {
      "action_name": "auto-egu",
      "description": "获取位置工程单位",
      "description_en": "Get the engineering units for position."
    },
    {
      "action_name": "auto-limits",
      "description": "获取行程限位",
      "description_en": "Get the travel limits."
    },
    {
      "action_name": "auto-moving",
      "description": "获取电机是否正在运动",
      "description_en": "Get whether the motor is moving."
    },
    {
      "action_name": "auto-position",
      "description": "获取当前位置",
      "description_en": "Get the current position."
    },
    {
      "action_name": "auto-report",
      "description": "获取电机状态报告",
      "description_en": "Get the motor status report."
    },
    {
      "action_name": "auto-get_lim",
      "description": "获取指定方向的行程限位",
      "description_en": "Get the travel limit for the selected direction."
    }
  ]
}

